_advance.body:
def _advance(state: np.ndarray, config: DynamicsConfig) -> np.ndarray:
    coefficients = np.tile(config.k, len(state) // 3)
    with np.errstate(over="raise", invalid="raise"):
        if len(state) == 3:
            coupling = np.asarray(L3) @ state
        else:
            coupling = np.roll(state, 1) + np.roll(state, -1) - 2 * state
        updated = (state + config.eps * state * (coefficients - np.abs(state) ** 2)
                   + config.g * coupling)
    return phase_sync(updated, config.phase_strength)

step3.body:
def step3(omega, config: DynamicsConfig) -> np.ndarray:
    """F_3: pre-sync amplitude map followed by the simultaneous synchronizer."""
    state = _state(omega)
    if len(state) != 3:
        raise ValueError("step3 requires exactly three components")
    return _advance(state, config)

z_chiral.body:
def z_chiral(omega):
    """Re(omega) cross Im(omega); a fresh real three-vector, without normalization.

    Checked real products reject subnormal/overflowing intermediates. Near
    cancellation, a zero or small computed value is not an exact-zero proof.
    """
    v = complex_vector(omega, 3, "omega")
    return np.array([total((product(v[j].real, v[k].imag, "z_chiral product"),
                            -product(v[k].real, v[j].imag, "z_chiral product")),
                           "z_chiral difference")
                     for j, k in ((1, 2), (2, 0), (0, 1))])
